import{_ as o,o as l,c as i,ah as r}from"./chunks/framework.DjU4PSOm.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"강의 오리엔테이션","slug":"강의-오리엔테이션","link":"#강의-오리엔테이션","children":[]},{"level":2,"title":"강의 로드맵 (총 6단계)","slug":"강의-로드맵-총-6단계","link":"#강의-로드맵-총-6단계","children":[]},{"level":2,"title":"윤리학의 세 가지 근본 질문","slug":"윤리학의-세-가지-근본-질문","link":"#윤리학의-세-가지-근본-질문","children":[]},{"level":2,"title":"윤리(Ethics) vs 도덕(Morality)","slug":"윤리-ethics-vs-도덕-morality","link":"#윤리-ethics-vs-도덕-morality","children":[]},{"level":2,"title":"실천철학으로서의 윤리학","slug":"실천철학으로서의-윤리학","link":"#실천철학으로서의-윤리학","children":[]},{"level":2,"title":"윤리학의 대상 — 5가지 차원","slug":"윤리학의-대상-—-5가지-차원","link":"#윤리학의-대상-—-5가지-차원","children":[]},{"level":2,"title":"윤리학의 6가지 핵심 질문","slug":"윤리학의-6가지-핵심-질문","link":"#윤리학의-6가지-핵심-질문","children":[]},{"level":2,"title":"기술적 판단 vs 규범적 판단","slug":"기술적-판단-vs-규범적-판단","link":"#기술적-판단-vs-규범적-판단","children":[]},{"level":2,"title":"윤리학의 세 영역","slug":"윤리학의-세-영역","link":"#윤리학의-세-영역","children":[]},{"level":2,"title":"Rachels, 『도덕철학의 요소들』 Ch.1 \\"What Is Morality?\\" — close reading","slug":"rachels-『도덕철학의-요소들』-ch-1-what-is-morality-—-close-reading","link":"#rachels-『도덕철학의-요소들』-ch-1-what-is-morality-—-close-reading","children":[]},{"level":2,"title":"도덕의 최소 개념 (Minimum Conception of Morality)","slug":"도덕의-최소-개념-minimum-conception-of-morality","link":"#도덕의-최소-개념-minimum-conception-of-morality","children":[]},{"level":2,"title":"사례 기반 방법론과 언어의 문제","slug":"사례-기반-방법론과-언어의-문제","link":"#사례-기반-방법론과-언어의-문제","children":[]},{"level":2,"title":"1주차 핵심 정리","slug":"_1주차-핵심-정리","link":"#_1주차-핵심-정리","children":[]}],"relativePath":"philosophy/Ethics/01. 윤리학이란 무엇인가.md","filePath":"philosophy/Ethics/01. 윤리학이란 무엇인가.md"}'),e={name:"philosophy/Ethics/01. 윤리학이란 무엇인가.md"};function a(s,t,n,u,q,h){return l(),i("div",null,[...t[0]||(t[0]=[r('<h2 id="강의-오리엔테이션" tabindex="-1">강의 오리엔테이션 <a class="header-anchor" href="#강의-오리엔테이션" aria-label="Permalink to &quot;강의 오리엔테이션&quot;">​</a></h2><ul><li>언어: 영어가 매개일 뿐 목표는 철학적 이해. 완벽한 영어가 필요하지 않으며, 시험은 영/한 모두 제공되고 답안도 아무 언어로나 작성 가능. Translive(AI 통번역)를 수업 중 사용할 수 있고 자료도 양 언어로 업로드됨</li><li>수업 방식: close reading(원전을 천천히 비판적으로 읽기) 중심. 발표·토론·매주 과제 없음. 원전을 자원해서 소리 내어 읽으면 가산점 제공</li><li>평가: 출석 10% / 중간고사 40% / 기말고사 40% / 참여 10%</li><li>교재: James Rachels &amp; Stuart Rachels, <em>The Elements of Moral Philosophy</em>, 10th ed. (McGraw Hill, 2023) — 1주차는 Ch.1 &quot;What Is Morality?&quot;</li></ul><h2 id="강의-로드맵-총-6단계" tabindex="-1">강의 로드맵 (총 6단계) <a class="header-anchor" href="#강의-로드맵-총-6단계" aria-label="Permalink to &quot;강의 로드맵 (총 6단계)&quot;">​</a></h2><ol><li>윤리학이란 무엇인가 — 개념 정의</li><li>덕윤리 — 아리스토텔레스</li><li>의무론 — 칸트</li><li>공리주의 — 벤담 &amp; 밀</li><li>정의론 — 롤스</li><li>메타윤리 &amp; AI — 무어, 에이어, 매키</li></ol><p>역사적(주요 철학자) + 개념적(핵심 윤리 개념) + 실천적(AI 등 현대 도덕 문제) 세 축으로 진행됨</p><h2 id="윤리학의-세-가지-근본-질문" tabindex="-1">윤리학의 세 가지 근본 질문 <a class="header-anchor" href="#윤리학의-세-가지-근본-질문" aria-label="Permalink to &quot;윤리학의 세 가지 근본 질문&quot;">​</a></h2><ul><li>어떻게 살아야 하는가?</li><li>무엇이 행위를 옳거나 그르게 만드는가?</li><li>도덕판단은 어떻게 정당화될 수 있는가?</li></ul><p>윤리학은 단순히 옳고 그름을 &#39;아는 것&#39;이 아니라 <strong>왜</strong> 옳은지를 묻는 것. 우리 사회의 도덕을 비판할 수 있는가, 도덕판단에도 더 정당한 것과 덜 정당한 것이 있는가, 도덕은 개인 의견일 뿐인가 아니면 이성으로 방어 가능한 주장인가 — 이런 물음들이 윤리학을 단순한 사적 취향이나 관습의 집합이 아니라 인간 행위를 이끄는 원칙·가치·이유를 검토하는 철학적 탐구로 만듦</p><h2 id="윤리-ethics-vs-도덕-morality" tabindex="-1">윤리(Ethics) vs 도덕(Morality) <a class="header-anchor" href="#윤리-ethics-vs-도덕-morality" aria-label="Permalink to &quot;윤리(Ethics) vs 도덕(Morality)&quot;">​</a></h2><ul><li>비유: <strong>도덕 : 윤리 = 언어 : 언어학 = 음악 : 음악학</strong>. 문법을 몰라도 말할 수 있듯, 도덕을 공부하지 않고도 품위 있게 행동할 수 있음. 도덕은 그냥 살아내는(lived) 것이고 윤리는 그것을 반성(reflected upon)하는 것</li><li>두 층위 구분 <ol><li>도덕(1층위) — 개인적 수준의 현상. 사람들이 실제로 따르는 가치·관습·관례·판단 체계. 가족이 아이에게 거짓말이 부끄럽다고 가르칠 때, 사회가 부패를 비난할 때, 약속을 어긴 뒤 죄책감을 느낄 때, 공동체가 관대함·정직함을 칭찬할 때 나타남. 누군가 이론화하기 이전부터 존재함 — 언어학자가 문법을 분석하기 전에 언어가 이미 존재하는 것처럼</li><li>윤리(2층위) — 도덕 규범을 단순히 반영하는 게 아니라, 한 걸음 물러서서 그 규범들이 정당한지 묻는 활동. 어떤 행위가 옳고 그른지, 도덕판단이 참일 수 있는지, 물려받은 관습이 우리의 충성을 받을 자격이 있는지, 일부 사회규범은 비판·변형되어야 하는지를 물음</li></ol><ul><li>이 구분이 절대적이진 않음(많은 철학자가 두 용어를 거의 동의어로 씀) — 하지만 이 강의에서는 윤리학을 인간 규범과 판단에 대한 철학적·비판적 탐구로 이해하는 데 도움을 줌</li></ul></li><li><strong>적용 예시 (나이 위계)</strong>: &quot;젊은 사람은 나이든 사람에게 항상 복종해야 한다&quot;는 믿음은 (특히 한국 사회에서) 그 사회의 일부로 존재함(도덕). 윤리는 여기서 더 나아가 묻는다 — 이 믿음은 정당한가? 나이가 항상 도덕적 권위를 부여하는가? 복종이 억압으로 변할 수 있는가? 위계 없이도 존중이 유지될 수 있는가?</li><li>정리: 도덕은 &quot;사람들이 이렇게 행동한다&quot;고 말하고, 윤리는 &quot;사람들이 이렇게 행동해야 하는가?&quot;라고 묻는다</li><li>어원 <ul><li>그리스어 <em>ēthos</em> — 성격, 습관, 삶의 방식. 윤리학은 어떤 규칙을 따르는가보다 <strong>무엇이 되는가</strong>의 문제</li><li>라틴어 <em>mos / mores</em> — 관습, 사회적 관행. 도덕은 인간이 함께 살아가는 방식에 뿌리내림</li></ul></li><li>철학의 역할: 가정·학교·사회·지역으로부터 물려받은 관습을 그대로 받아들이지 않고, 그것이 사람을 존중하는지·부정의를 낳는지·인간이 잘 살도록 허용하는지 묻는 것</li></ul><h2 id="실천철학으로서의-윤리학" tabindex="-1">실천철학으로서의 윤리학 <a class="header-anchor" href="#실천철학으로서의-윤리학" aria-label="Permalink to &quot;실천철학으로서의 윤리학&quot;">​</a></h2><p>아리스토텔레스의 삼분법 (이성의 세 지향)</p><ol><li><strong>theōria (관조/이론)</strong>: 목표는 지식. 대상은 달리 있을 수 없는 것 — 수학·형이상학의 필연적·영원한 진리</li><li><strong>praxis (실천)</strong>: 목표는 인간 선택의 세계에서 행위하는 것. 상황이 달라질 수 있고 숙고가 필요한 영역 — <strong>윤리학과 정치학이 여기 속함</strong></li><li><strong>poiēsis (제작)</strong>: 활동 자체 바깥에 목적이 있는 것을 만드는 것 — 집을 짓거나 배를 만들거나 시를 쓰는 것</li></ol><p>윤리학은 praxis에 속함. 목적은 이론적 지식이 아니라 좋은 행위이며, 아리스토텔레스가 『니코마코스 윤리학』에서 말하듯 &quot;덕이 무엇인지 알기 위해서가 아니라 좋은 사람이 되기 위해&quot; 윤리학을 공부함. (수학에서는 이 주장이 이상하게 들릴 것 — 아무도 더 나은 삼각형이 되려고 피타고라스 정리를 공부하지 않음. 그러나 윤리학에서는 지식과 좋은 사람이 되는 것이 긴밀히 연결됨)</p><p>두 가지 함의</p><ol><li><strong>맥락적 정밀성</strong>: 인간 상황은 다양하고 예상치 못한 요인을 마주하므로, 판단은 특정 상황에 반응적이어야 함. 모호하거나 부주의해도 된다는 뜻이 아니라, 맥락에 눈감지 않으면서도 엄격해야 한다는 뜻</li><li><strong>인식주체의 연루</strong>: 천문학자의 성격이 천문학적 진리에 영향을 주지 않는 것과 달리, 도덕적 이해는 삶의 경험과 습관화(habituation)로 형성됨 — 아리스토텔레스가 삶의 경험이 부족한 사람은 윤리학을 더 어렵게 느낄 수 있다고 본 이유(지능 부족이 아니라 윤리적 성찰이 살아온 경험에서 출발해 다시 그리로 돌아가기 때문)</li></ol><p>다른 철학 분과와의 대비: 형이상학은 &quot;무엇이 존재하는가&quot;, 인식론은 &quot;지식이란 무엇인가&quot;, 논리학은 &quot;타당한 추론이란 무엇인가&quot;를 묻는 반면, 윤리학은 &quot;어떻게 살아야 하는가, 나는 어떤 사람이 되어야 하는가, 어떤 공동체를 만들어야 하는가, 어떤 제도가 정의로운가&quot;를 물음. 실천철학은 쉬운 철학도, 이론 없는 철학도 아님 — 진지한 이론적 성찰을 요구하되 최종 관심사가 인간의 행동·결정·책임·삶이라는 점이 다름. (예: 이론이성은 &quot;기후변화가 과학적으로 실재하는가&quot;를 묻고, 실천이성은 &quot;우리가 그에 대해 무엇을 해야 하는가&quot;를 물음. 이론이성은 &quot;AI가 데이터를 효율적으로 처리할 수 있는가&quot;를 묻고, 실천이성은 &quot;AI가 채용·치안·교육·복지 결정을 내리도록 허용해야 하는가&quot;를 물음)</p><h2 id="윤리학의-대상-—-5가지-차원" tabindex="-1">윤리학의 대상 — 5가지 차원 <a class="header-anchor" href="#윤리학의-대상-—-5가지-차원" aria-label="Permalink to &quot;윤리학의 대상 — 5가지 차원&quot;">​</a></h2><ol><li><strong>행위</strong>: 거짓말, 돕기, 해치기, 배신, 약속</li><li><strong>성품</strong>: 용기, 정직, 오만, 관대함, 비겁함 — 고립된 행동이 아니라 삶의 방식을 형성하는 지속적 특성</li><li><strong>규칙과 원칙</strong>: &quot;거짓말하지 말라&quot;, &quot;타인을 존중하라&quot;, &quot;약속을 지켜라&quot;, &quot;행복을 극대화하라&quot;</li><li><strong>제도</strong>: 학교, 법원, 시장, 정부, 병원, 디지털 플랫폼 — 권력·기회·취약성·인정을 분배하기 때문에 도덕적으로 평가 가능. 개인들이 정중하게 행동해도 사회 제도 자체는 부당할 수 있음</li><li><strong>삶의 방식</strong>: 돈·쾌락·공공봉사·지적 탐구에 헌신하는 삶</li></ol><p>심리학·사회학·인류학과 달리(이들은 &quot;왜 죄책감을 느끼는가&quot;, &quot;도덕규범이 사회에서 어떻게 기능하는가&quot;, &quot;관습이 문화마다 어떻게 다른가&quot;를 기술적으로 물음), 윤리학은 행위·규칙·성품·제도·삶의 방식이 <strong>도덕적으로 정당한지</strong>를 규범적으로 물음 — 한 가지 고립된 행위의 옳고 그름보다 훨씬 넓은 범위</p><h2 id="윤리학의-6가지-핵심-질문" tabindex="-1">윤리학의 6가지 핵심 질문 <a class="header-anchor" href="#윤리학의-6가지-핵심-질문" aria-label="Permalink to &quot;윤리학의 6가지 핵심 질문&quot;">​</a></h2><ol><li>무엇을 해야 하는가 → <strong>행위</strong></li><li>어떤 사람이 되어야 하는가 → <strong>성품</strong></li><li>타인에게 무엇을 빚지고 있는가 → <strong>의무</strong></li><li>정의란 무엇인가 → <strong>제도</strong></li><li>도덕판단은 참일 수 있는가 → <strong>메타윤리</strong></li><li>AI를 어떻게 규제해야 하는가 → <strong>응용윤리</strong></li></ol><p>이 강의는 이 질문들을 하나의 답으로 환원하지 않고, 각기 다른 철학적 대응을 살펴봄: 아리스토텔레스(덕과 인간적 번영), 칸트(의무·자율·존엄), 벤담&amp;밀(결과·쾌락·효용), 롤스(정의와 공정한 사회제도), 무어·에이어·매키(도덕언어의 의미·객관성), 그리고 이 모든 접근을 현대 기술사회(AI)에 적용</p><h2 id="기술적-판단-vs-규범적-판단" tabindex="-1">기술적 판단 vs 규범적 판단 <a class="header-anchor" href="#기술적-판단-vs-규범적-판단" aria-label="Permalink to &quot;기술적 판단 vs 규범적 판단&quot;">​</a></h2><ul><li><strong>기술적(descriptive) 판단</strong>: 사실 여부로 참/거짓이 갈림. 예) &quot;많은 학생이 수업 중 스마트폰을 쓴다&quot;, &quot;일부 기업이 채용에 AI를 쓴다&quot;, &quot;어떤 사람은 갈등을 피하려 거짓말을 한다&quot;</li><li><strong>규범적(normative) 판단</strong>: 마땅히 그래야 하는 것에 대한 주장, 이유·가치·기준이 필요함. 예) &quot;학생은 무관한 용도로 폰을 쓰면 안 된다&quot;, &quot;기업은 편향된 AI 채용 시스템을 쓰면 안 된다&quot;, &quot;단지 불편함을 피하려 거짓말해선 안 된다&quot;</li><li>윤리학은 주로 규범적 주장에 집중하지만, 정확한 기술적 정보에 의존함 — AI 채용 시스템이 공정한지 판단하려면 그것이 어떻게 작동하고 어떤 데이터를 쓰며 특정 집단에 불이익을 주는지부터 알아야 하고, 그다음 공정성·평등·존엄성·책임성·인간의 감독을 존중하는지 물어야 함</li><li><strong>흔한 오류</strong>: 기술적 사실에서 규범적 결론으로 성급히 건너뛰는 것. &quot;다들 부정행위를 하니까(혹은 생성 AI로 과제를 대신 쓰니까) 괜찮다&quot; — 흔하다는 사실이 옳음을 뜻하지 않음. &quot;이 관습은 오래됐으니 도덕적으로 정당하다&quot; — 오래된 관습도 여전히 부당할 수 있음. 윤리학은 항상 <strong>이유</strong>를 요구하며, 흔한 것과 옳은 것을 혼동하지 않도록 가르침</li></ul><h2 id="윤리학의-세-영역" tabindex="-1">윤리학의 세 영역 <a class="header-anchor" href="#윤리학의-세-영역" aria-label="Permalink to &quot;윤리학의 세 영역&quot;">​</a></h2><ol><li><strong>규범윤리학(Normative Ethics)</strong>: 어떤 원칙·덕·의무가 행위를 이끌어야 하는가, 무엇이 옳고 그름을 만드는가, 어떤 삶이 좋은 삶인가. 덕윤리, 의무론, 공리주의 포함</li><li><strong>메타윤리학(Metaethics)</strong>: 도덕 용어는 무엇을 의미하는가, 도덕판단은 참/거짓일 수 있는가, 도덕적 가치는 객관적인가 주관적인가, &quot;옳음이 그름이다&quot;라고 말할 때 우리는 사실을 인용하는가·감정을 표현하는가·처방을 내리는가·사회적 관행에 참여하는가</li><li><strong>응용윤리학(Applied Ethics)</strong>: 윤리 이론·개념을 구체적 문제에 적용 — 생명윤리, 환경윤리, 동물윤리, AI윤리. 이 강의의 주요 응용 주제는 AI — AI 시스템이 공정·책임·투명하며 인간 존엄을 존중할 수 있는지, 알고리즘 차별/의사결정이 교육·고용·의료·면허·지식생산·민주적 공론장에서 윤리적으로 정당할 수 있는지</li></ol><p>세 영역을 통해 윤리학은 도덕판단의 토대를 탐구하는 동시에 현대의 도덕 문제에 책임감 있게 사고하도록 도움</p><h2 id="rachels-『도덕철학의-요소들』-ch-1-what-is-morality-—-close-reading" tabindex="-1">Rachels, 『도덕철학의 요소들』 Ch.1 &quot;What Is Morality?&quot; — close reading <a class="header-anchor" href="#rachels-『도덕철학의-요소들』-ch-1-what-is-morality-—-close-reading" aria-label="Permalink to &quot;Rachels, 『도덕철학의 요소들』 Ch.1 &quot;What Is Morality?&quot; — close reading&quot;">​</a></h2><p><strong>소크라테스 인용으로 시작하는 이유</strong>: &quot;우리는 사소한 문제가 아니라 어떻게 살아야 하는가를 논하고 있다&quot;(플라톤 『국가』). 저자들은 특정 이론(공리주의·칸트주의)이 아니라 가장 근본적이고 어려운 질문 — &quot;도덕이란 무엇인가&quot;(1장 제목) — 에서 출발함. 이는 사전적 정의 요청이 아니라 인간의 행위·삶의 방식·타인에 대한 책임·옳고 그름의 기준·좋은 삶의 조건을 아우르는 물음</p><p><strong>&quot;어떻게 살아야 하는가&quot;의 구조 분석</strong></p><ul><li>How = 삶의 방식·형태</li><li>We = 개인뿐 아니라 공동체로서의 인간</li><li>Ought to = 단순한 사실이 아니라 규범성</li><li>Live = 고립된 행위가 아니라 삶 전체</li></ul><p>→ 윤리학은 규칙 암기가 아니라 인간 삶 전체의 방향성에 대한 탐구. (예: &quot;시험에서 부정행위를 하면 안 된다&quot;는 구체적 규칙이지만, 윤리학은 더 깊이 — &quot;나는 신뢰할 수 있는 사람이 되고 싶은가, 아니면 결과만 생각하는 사람이 되고 싶은가&quot;를 물음)</p><p><strong>소크라테스와 &quot;성찰하지 않는 삶&quot;</strong>: &quot;성찰하지 않는 삶은 살 가치가 없다.&quot; 소크라테스에게 윤리학은 외부에서 주어진 답의 암기가 아니라 삶 자체를 검토하는 활동. (강의에서 언급된 &quot;먹는 데만 관심 있는 만족한 짐승&quot;의 비유는 성찰 없는 삶을 상징함) 윤리학은 옳고 그름의 규칙을 외우는 게 아니라 새로운 문제와 질문을 스스로 만들어내도록 요구함</p><p><strong>정의(定義)의 문제</strong>: 도덕을 정의하는 것 자체가 이미 하나의 이론적 입장을 함축함</p><ul><li>&quot;도덕 = 행복의 극대화&quot; → 공리주의적 정의</li><li>&quot;도덕 = 의무를 따르는 것&quot; → 칸트적 의무론</li><li>&quot;도덕 = 좋은 성품의 형성&quot; → 아리스토텔레스적 덕윤리</li></ul><p>즉 도덕을 어떻게 정의하느냐가 이미 삶과 세계에 대한 이해를 반영함 — 철학에서 정의는 중립적 출발점이 아니라 이미 하나의 철학적 선택</p><p><strong>&quot;도덕이란 무엇인가&quot; vs &quot;도덕이 우리에게 무엇을 요구하는가&quot;</strong>: 도덕철학은 두 층위를 가짐</p><ol><li>도덕이 무엇인가 (개념적 질문) — 도덕판단은 의견·감정·관습·사회규범의 문제인가</li><li>도덕이 우리에게 무엇을 요구하는가 (규범적 질문) — 우리는 타인을 어떻게 대해야 하는가</li></ol><p>예) &quot;거짓말은 왜 그른가&quot;는 첫 번째 층위, &quot;누군가의 감정을 지키려고 거짓말해도 되는가&quot;는 두 번째 층위</p><p><strong>&quot;어떻게, 그리고 왜(and why)&quot;</strong>: 이 &quot;그리고 왜&quot;가 핵심. 윤리학은 단순히 특정 방식으로 살라고 명령하는 게 아니라 왜 그래야 하는지를 물음 — 이 점에서 권위주의적 도덕교육(&quot;해야 하니까 해야 한다&quot;)과 다름. 철학적 윤리학은 &quot;왜 우리가 이것을 해야 하는가&quot;를 물음. (예: &quot;자녀는 부모에게 순종해야 한다&quot; → 왜인가? 감사 때문인가, 의존 때문인가? 부모의 명령이 부당해도 순종해야 하는가?) 핵심: <strong>윤리학은 규범 + 이유의 학문</strong> — 도덕적 명령에 이유를 제시할 수 없다면 그 명령이 여전히 도덕적 권위를 가질 수 있는지 물을 수 있음</p><p><strong>정의의 불가능성과 이론의 다원성</strong>: 소크라테스의 넓은 정식(&quot;어떻게 살아야 하는가&quot;)을 넘어서는 구체적 정의는 반드시 어느 한 이론과 충돌함 — 도덕은 수학처럼 공리에서 출발할 수 없는, 철학적으로 논쟁적인 개념이기 때문. (예: 낙태 논쟁 — 태아의 생명권에 초점을 두는 입장, 신체 자율성에 초점을 두는 입장, 고통·사회적 조건·돌봄의 책임에 초점을 두는 입장 모두 도덕판단을 주장하지만 무엇을 우선할지가 다름) 아리스토텔레스는 덕과 인간적 번영, 칸트는 이성과 보편법칙, 공리주의는 최대다수의 최대행복, 롤스는 공정한 조건에서 선택될 원칙으로 도덕적 삶을 이해함</p><p><strong>적용 사례 (친구의 부정행위)</strong>: 친구가 시험에서 부정행위를 한 걸 봤다면? 덕윤리는 &quot;정직하고 용기 있는 사람이라면 어떻게 할까&quot;를 묻고, 의무론은 &quot;부정행위를 용인하는 원칙이 보편화될 수 있는가&quot;를 묻고, 공리주의는 &quot;어느 쪽이 더 큰 해를 줄이는가&quot;를 물음 — 같은 문제에 대해 이론마다 다른 물음을 던짐</p><p><strong>불일치가 마비를 뜻하지 않음</strong>: &quot;이것은 우리를 신중하게 해야 하지만 마비시켜서는 안 된다.&quot; 저자들은 두 극단을 피함</p><ul><li><strong>독단주의</strong>: &quot;다들 이미 도덕이 뭔지 안다&quot;</li><li><strong>회의적 마비</strong>: &quot;의견이 다르니 아무것도 판단할 수 없다&quot;</li></ul><p>중간 입장: 신중하되 도덕적 성찰을 포기하지 않음. (예: AI 윤리에 대해 사람들 의견이 갈린다고 해서 알고리즘 차별·감시·사생활 침해 같은 문제를 판단할 수 없는 건 아님 — 판단이 오류 가능하더라도 더 나은 이유와 원칙을 계속 찾아야 함)</p><h2 id="도덕의-최소-개념-minimum-conception-of-morality" tabindex="-1">도덕의 최소 개념 (Minimum Conception of Morality) <a class="header-anchor" href="#도덕의-최소-개념-minimum-conception-of-morality" aria-label="Permalink to &quot;도덕의 최소 개념 (Minimum Conception of Morality)&quot;">​</a></h2><p>Rachels는 최종적인 도덕의 정의 대신, 모든 도덕이론이 최소한 받아들여야 할 <strong>출발점 조건</strong>을 제시함 — &quot;더 정교한 정의&quot;가 아니라 &quot;무언가가 도덕으로 인정받으려면 최소한 갖춰야 할 것&quot;</p><p>두 가지 최소조건</p><ol><li>자신의 행동을 <strong>이유(reason)</strong>로 이끌려는 노력</li><li>자신의 결정에 영향받는 모든 이해당사자의 이익에 <strong>동등한 비중</strong>을 두려는 노력</li></ol><p>예) &quot;나는 그냥 그렇게 느끼기 때문에 이 행동이 잘못됐다고 생각한다&quot;는 아직 최소조건을 충족하지 못함 — 도덕판단은 이유를 필요로 하기 때문</p><p>이는 일종의 방법론적 보편성: 이론마다 결론은 다르지만, 도덕판단이 자의적이거나 비합리적이거나 불공정하게 편파적이어서는 안 된다는 데는 동의해야 함 (예: 공리주의자는 행복을, 칸트주의자는 의무를 강조하지만, 둘 다 &quot;이유 없는 도덕판단&quot;은 인정하지 않음)</p><h2 id="사례-기반-방법론과-언어의-문제" tabindex="-1">사례 기반 방법론과 언어의 문제 <a class="header-anchor" href="#사례-기반-방법론과-언어의-문제" aria-label="Permalink to &quot;사례 기반 방법론과 언어의 문제&quot;">​</a></h2><p>Rachels는 추상적 정의가 아니라 구체적이고 논쟁적인 사례에서 시작해 도덕적 추론의 구조를 드러내는 <strong>사례 기반(case-based)</strong> 방법을 씀 — &quot;장애 아동과 관련된 도덕적 논쟁들&quot;을 예로 들며 최소 개념의 특징을 도출</p><p><strong>언어 감수성에 대한 메모</strong>: 교재 원문의 &quot;handicapped children&quot;이라는 표현은 오늘날 &quot;children with disabilities&quot;(장애가 있는 아동)로 쓰는 것이 더 적절함 — &quot;handicapped&quot;는 역사적으로 흔히 쓰였지만 지금은 낙인적으로 들릴 수 있음. 오래된 철학 텍스트를 읽을 때 원문의 언어를 그대로 받아들일지, 현대의 윤리적 감수성에 비추어 비판적으로 읽을지를 스스로 물어야 함 — 낡은 용어가 상식과 학술 담론에까지 편견을 재생산할 수 있기 때문. 장애 아동 관련 생명윤리 논쟁의 핵심 질문은 &quot;그들의 삶이 덜 가치 있는가&quot;가 아니라 &quot;삶·고통·자율성·보호·차별·돌봄의 책임을 어떻게 함께 고려할 것인가&quot;</p><p>이 방법은 AI윤리에도 그대로 적용됨: AI가 구직자를 자동 선별할 때 여성·장애인·특정 지역 출신 지원자가 불리해질 수 있음(한국에서는 서울 소재 학위와 지방 소재 학위 간 기회 격차가 실제로 존재). 기업은 효율성에, 윤리는 공정성·차별에 초점을 둠 — 어느 이유가 더 강한지, 누구의 이익이 고려되었는지, 어떤 도덕원칙이 적용되어야 하는지를 물어야 함</p><h2 id="_1주차-핵심-정리" tabindex="-1">1주차 핵심 정리 <a class="header-anchor" href="#_1주차-핵심-정리" aria-label="Permalink to &quot;1주차 핵심 정리&quot;">​</a></h2><ul><li>윤리학은 어떻게 살아야 하는지와 <strong>그 이유</strong>를 묻는 것 — 규칙의 목록이 아니라 삶 전체의 방향에 대한 철학적 탐구</li><li>도덕은 간단하고 통일된 방식으로 정의될 수 없음 — 윤리 이론마다 도덕적 삶을 다르게 이해하기 때문</li><li>그러나 이 불일치가 도덕철학을 불가능하게 만들지는 않음 — 오히려 정교한 철학적 성찰을 <strong>필요</strong>하게 만듦</li><li>도덕철학의 과제: 이유를 검토하고, 개념을 명료화하고, 사례를 분석하고, 정당화된 도덕판단의 최소조건을 찾는 것</li></ul><hr><p>출처: KNU Canvas TransLive 실시간 자막 전문(윤지영 교수, 윤리학 001분반, 1주차) + 강의 슬라이드 <code>26-2 Ethics-Week-1.pdf</code>. 원문 자막은 저작권 문제로 공개 리포지토리에는 올리지 않고 <code>_raw/</code> 폴더(gitignore)에 개인 보관.</p>',60)])])}const p=o(e,[["render",a]]);export{c as __pageData,p as default};
